from .repository import contact_exists, put_contact

_REQUIRED_FIELDS = {"email", "name"}


def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)


def _normalize_import_rows(rows):
    """Validate a complete batch and return normalized (email, name) pairs.

    Raises ValueError if anything in the batch is invalid; no writes happen
    here, so a rejected batch never touches the database.
    """
    try:
        rows = list(rows)
    except TypeError as exc:
        raise ValueError("rows must be an iterable of objects") from exc

    normalized = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict) or set(row.keys()) != _REQUIRED_FIELDS:
            raise ValueError(
                "Each row must be an object containing exactly 'email' and 'name'"
            )

        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("'email' and 'name' must be strings")

        email = email.strip()
        name = name.strip()

        if email.count("@") != 1:
            raise ValueError("Email must contain exactly one '@'")
        local, domain = email.split("@")
        if not local or not domain or any(char.isspace() for char in email):
            raise ValueError("Email must have nonempty sides and no whitespace")
        email = email.lower()

        if not name:
            raise ValueError("'name' must not be empty")

        if email in seen:
            raise ValueError("Duplicate email in batch: %s" % (email,))
        seen.add(email)

        normalized.append((email, name))

    return normalized


def import_contacts(connection, rows):
    normalized = _normalize_import_rows(rows)
    if not normalized:
        return {"inserted": 0, "updated": 0}

    inserted = 0
    updated = 0

    # The connection is idle at entry, so this begins a fresh transaction.
    # Doing it explicitly keeps the batch atomic even on autocommit
    # connections (isolation_level=None), while commit()/rollback() still
    # behave correctly for the default connection mode.
    if not connection.in_transaction:
        connection.execute("BEGIN")
    try:
        with connection:
            for email, name in normalized:
                if contact_exists(connection, email):
                    updated += 1
                else:
                    inserted += 1
                put_contact(connection, email, name)
    except BaseException:
        if connection.in_transaction:
            connection.rollback()
        raise

    return {"inserted": inserted, "updated": updated}
